    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'The Heritage Clothes exhibition was put together by','[{"text":"museum staff.","letter":"A"},{"letter":"B","text":"local residents."},{"letter":"C","text":"clothing manufacturers."}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'The photographs show the clothes worn by','[{"text":"their owners.","letter":"A"},{"letter":"B","text":"professional models."},{"letter":"C","text":"design students."}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'The exhibition called Toys from the Past is','[{"letter":"A","text":"displayed in a new gallery."},{"letter":"B","text":"on show for a limited time."},{"letter":"C","text":"aimed specially at children."}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,14,'Visitors to Toys from the Past are recommended to','[{"text":"play with the toy trains.","letter":"A"},{"letter":"B","text":"look at all the dolls."},{"letter":"C","text":"see the board games."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,15,'The miniature toys have been','[{"text":"made by the museum.","letter":"A"},{"text":"bought by the museum.","letter":"B"},{"letter":"C","text":"borrowed by the museum."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,16,'The biscuit factory made tins','[{"letter":"A","text":"for people all over the world."},{"text":"of different shapes.","letter":"B"},{"text":"for many famous people.","letter":"C"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,17,'People''s favourite biscuit used to be','[{"text":"an unsweetened one.","letter":"A"},{"letter":"B","text":"one covered in chocolate."},{"text":"one filled with cream.","letter":"C"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,18,'The hands-on activity allows people to','[{"letter":"A","text":"make some biscuits."},{"letter":"B","text":"taste some of the biscuits."},{"letter":"C","text":"pack a biscuit tin."}]'::jsonb,'"C"'::jsonb);
