    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,21,'Pacific tapa cloth is different from other types of tapa cloth because it is','[{"text":"the only tapa made today","letter":"A"},{"text":"better quality than others","letter":"B"},{"text":"put to a wider range of uses","letter":"C"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,22,'What does Helen say about the paper mulberry tree?','[{"letter":"A","text":"It is also a source of food"},{"text":"It is not native to the Pacific","letter":"B"},{"letter":"C","text":"It can grow in any environment"}]'::jsonb,'"B"'::jsonb);
